const BY_PATH = new Map<string, SandboxDescriptor>(
  SANDBOX_DESCRIPTORS.map((d) => [d.path, d]),
);

export function describeSandbox(path: string): SandboxDescriptor | undefined {
  return BY_PATH.get(path);
}

